def add(n,title,scans,kind,quote,body,context,ledger,query,checks):
 items.append(dict(id=f'C64-N{n:02d}',title=title,scans=scans,kind=kind,quote=quote,body=body,context=context,ledger=ledger,query=query,checks=checks))
